// GENERATED by scripts/import_malloy.mjs from the malloy-render library — do not edit.
// Only the imports are rewritten (remotion frame hooks -> ../remotionShim, google fonts ->
// ../googleFonts, zod schema removed since its fields now live in the adapter's params).
import React from "react";
import {
  useCurrentFrame,
  useVideoConfig,
  AbsoluteFill,
  interpolate,
  Easing,
} from '../remotionShim';
import { Triangle } from "@remotion/shapes";

// --- Google Fonts Loader ---
const useFontLoader = (fonts: string[]) => {
  const stableFonts = React.useMemo(() => {
    const unique = [...new Set(fonts.map((f) => f.trim()))].sort();
    return unique;
  }, [fonts.join("|")]);

  React.useEffect(() => {
    const unloaded = stableFonts.filter(
      (font) =>
        !document.querySelector(
          `link[href*="${font.replace(/\s+/g, "+")}"]`
        )
    );

    if (unloaded.length === 0) return;

    const url = `https://fonts.googleapis.com/css2?${unloaded
      .map(
        (font) => `family=${font.replace(/\s+/g, "+")}:wght@400;600;700`
      )
      .join("&")}&display=swap`;

    const link = document.createElement("link");
    link.rel = "stylesheet";
    link.href = url;

    document.head.appendChild(link);
  }, [stableFonts]);
};

// --- Schema Definition ---


export type ScrollingWordListProps = Record<string, any>;

// --- Component ---
const ScrollingWordList: React.FC<ScrollingWordListProps> = ({
  backgroundColor = "#f4f4f4",
  transparentBackground = false,
  durationInSeconds = 5,
  wordList = "Driven, Vision, Momentum, Focus, Strength, Forge, Pursuit, Flow",
  startWord = "Focus",
  endWord = "Pursuit",
  logoImage = "https://malloy.blob.core.windows.net/web/testing/ChatGPT-Logo.png",
  primaryTextColor = "#1a1a1a",
  highlightColor = "#ff6b6b",
  fontSize = 80,
}) => {
  useFontLoader(["Inter"]);

  const frame = useCurrentFrame();
  const { fps, width, height } = useVideoConfig();
  const durationInFrames = durationInSeconds * fps;

  // Safe color parsing
  const bgStyle = transparentBackground ? "transparent" : backgroundColor;

  // --- Layout Constants ---
  // Split screen: Left for Logo, Right for List
  const LEFT_COL_WIDTH = width * 0.4;
  const RIGHT_COL_WIDTH = width * 0.6;
  
  // List Area
  const ROW_HEIGHT = fontSize * 1.5;
  const LIST_CENTER_Y = height / 2; // Vertically centered on screen

  // --- Data Parsing ---
  const parsedWordList = React.useMemo(() => {
    return wordList
      .split(/[\n,]+/)
      .map((w) => w.trim())
      .filter((w) => w.length > 0);
  }, [wordList]);

  const safeStart = parsedWordList.includes(startWord)
    ? startWord
    : parsedWordList[0];
  const safeEnd = parsedWordList.includes(endWord)
    ? endWord
    : parsedWordList[parsedWordList.length - 1];

  // Construct scrolling path
  const displayList = React.useMemo(() => {
    const listLength = parsedWordList.length;
    if (listLength === 0) return [];

    const startIndex = parsedWordList.indexOf(safeStart);
    let path: string[] = [];
    let currentIndex = startIndex;
    let foundEnd = false;
    let iterations = 0;

    while (!foundEnd && iterations < listLength * 2) {
      const word = parsedWordList[currentIndex % listLength];
      path.push(word);
      if (word === safeEnd && iterations > 0) foundEnd = true;
      currentIndex++;
      iterations++;
    }

    const paddingCount = 6;
    const prefix = Array.from({ length: paddingCount }).map((_, i) => {
      const idx = (startIndex - paddingCount + i + listLength * 10) % listLength;
      return parsedWordList[idx];
    });

    const suffix = Array.from({ length: paddingCount }).map((_, i) => {
      const idx = (currentIndex + i) % listLength;
      return parsedWordList[idx];
    });

    return [...prefix, ...path, ...suffix];
  }, [parsedWordList, safeStart, safeEnd]);

  const paddingCount = 6;
  const activeStartIndex = paddingCount;
  const activeEndIndex = displayList.length - paddingCount - 1;

  // --- Animation Calculations ---
  
  // We want to center the 'active' item at LIST_CENTER_Y
  const getContainerY = (targetIndex: number) => {
    return LIST_CENTER_Y - targetIndex * ROW_HEIGHT - ROW_HEIGHT / 2;
  };

  const startY = getContainerY(activeStartIndex);
  const endY = getContainerY(activeEndIndex);

  const progress = interpolate(frame, [0, durationInFrames], [0, 1], {
    easing: Easing.inOut(Easing.cubic),
    extrapolateLeft: "clamp",
    extrapolateRight: "clamp",
  });

  const currentContainerY = interpolate(progress, [0, 1], [startY, endY]);

  // Logo Animation
  const logoOpacity = interpolate(frame, [0, 20], [0, 1], {
    extrapolateRight: "clamp",
  });
  const logoScale = interpolate(frame, [0, 25], [0.9, 1], {
    easing: Easing.out(Easing.back(1.5)),
    extrapolateRight: "clamp",
  });

  return (
    <AbsoluteFill style={{ backgroundColor: bgStyle }}>
      
      {/* --- Left Column: Logo --- */}
      <AbsoluteFill
        style={{
          width: LEFT_COL_WIDTH,
          height: height,
          left: 0,
          top: 0,
          zIndex: 20,
          justifyContent: "center",
          alignItems: "center",
        }}
      >
        <div 
          style={{ 
            opacity: logoOpacity, 
            transform: `scale(${logoScale})`,
            display: "flex",
            justifyContent: "center",
            alignItems: "center",
            width: "80%", // Padding
          }}
        >
          {logoImage ? (
            <img
              src={logoImage}
              alt="Logo"
              style={{
                maxWidth: "100%",
                maxHeight: height * 0.4, // Limit height so it doesn't take over
                objectFit: "contain",
              }}
            />
          ) : null}
        </div>
      </AbsoluteFill>

      {/* --- Right Column: List Section --- */}
      <AbsoluteFill
        style={{
          left: LEFT_COL_WIDTH,
          width: RIGHT_COL_WIDTH,
          height: height,
          top: 0,
          overflow: "hidden",
        }}
      >
        {/* The Scrolling Container */}
        <div
          style={{
            position: "absolute",
            top: 0,
            left: 0,
            width: "100%",
            transform: `translateY(${currentContainerY}px)`,
            display: "flex",
            flexDirection: "column",
            alignItems: "flex-start",
          }}
        >
          {displayList.map((word, i) => {
            const itemCenterY = currentContainerY + i * ROW_HEIGHT + ROW_HEIGHT / 2;
            const distFromCenter = Math.abs(itemCenterY - LIST_CENTER_Y);
            
            // Logic for visual prominence
            const isActive = distFromCenter < ROW_HEIGHT / 2;
            const itemScale = interpolate(distFromCenter, [0, height * 0.4], [1, 0.85], { extrapolateRight: "clamp" });
            const itemOpacity = interpolate(distFromCenter, [0, height * 0.4], [1, 0.3], { extrapolateRight: "clamp" });
            const itemColor = isActive ? highlightColor : primaryTextColor;

            return (
              <div
                key={`${word}-${i}`}
                style={{
                  height: ROW_HEIGHT,
                  width: "100%",
                  display: "flex",
                  alignItems: "center",
                  paddingLeft: width * 0.08, // Indent slightly in the column
                  fontFamily: "Inter",
                  fontWeight: 700,
                  fontSize: fontSize,
                  color: itemColor,
                  opacity: itemOpacity,
                  transform: `scale(${itemScale})`,
                  transformOrigin: "left center",
                }}
              >
                {word}
              </div>
            );
          })}
        </div>

        {/* --- Gradient Masks (Scoped to Right Column) --- */}
        {/* Top Mask */}
        <div
          style={{
            position: "absolute",
            top: 0,
            left: 0,
            width: "100%",
            height: height * 0.3,
            background: `linear-gradient(to bottom, ${bgStyle} 10%, transparent 100%)`,
            pointerEvents: "none",
            zIndex: 5,
          }}
        />
        {/* Bottom Mask */}
        <div
          style={{
            position: "absolute",
            bottom: 0,
            left: 0,
            width: "100%",
            height: height * 0.3,
            background: `linear-gradient(to top, ${bgStyle} 10%, transparent 100%)`,
            pointerEvents: "none",
            zIndex: 5,
          }}
        />
      </AbsoluteFill>

      {/* --- Selection Indicator (Triangle) --- */}
      {/* Positioned relative to the boundary of the columns */}
      <AbsoluteFill
        style={{
          pointerEvents: "none",
          zIndex: 15,
        }}
      >
        <div 
          style={{ 
            position: "absolute",
            top: LIST_CENTER_Y,
            left: LEFT_COL_WIDTH + (width * 0.03), // Offset slightly into the right column
            transform: "translateY(-50%)",
            display: "flex",
            alignItems: "center"
          }}
        >
          <Triangle
            length={fontSize * 0.5}
            direction="right"
            fill={highlightColor}
            style={{ opacity: 1 }}
          />
        </div>
      </AbsoluteFill>

    </AbsoluteFill>
  );
};

export default ScrollingWordList;